// Stage 3's Node equivalence proof: the transcript recorded by the REAL
// Go handler (internal/server/testdata/c7-two-round.json, regenerated by
// `UPDATE_TRANSCRIPT=1 go test ./internal/server -run TestC7TranscriptFixture`)
// is replayed through the REAL client — app.js's startGeneration over the
// real sse.js loop — and the bubbles it paints must carry exactly the
// ids the same recording's GET /messages returns. Live == history, in
// Node, on recorded reality. Run: make test-js.
import { test } from "node:test";
import assert from "node:assert/strict";
import { register } from "node:module";
import { readFileSync } from "node:fs";

register("./resolver.mjs", import.meta.url);

const fx = JSON.parse(
  readFileSync(new URL("../../internal/server/testdata/c7-two-round.json", import.meta.url), "utf8"),
);

// --- minimal stub DOM (enough for the streamed bubbles themselves) ---------
function makeEl() {
  const el = {
    tagName: "DIV",
    style: {},
    dataset: {},
    classList: { add() {}, remove() {}, toggle() {}, contains() { return false; } },
    children: [],
    hidden: false,
    disabled: false,
    value: "",
    textContent: "",
    open: false,
    append(...es) { this.children.push(...es); },
    appendChild(e) { this.children.push(e); return e; },
    replaceChildren(...es) { this.children = es; },
    before() {},
    remove() {
      const p = this._parent;
      if (p) {
        const i = p.children.indexOf(this);
        if (i >= 0) p.children.splice(i, 1);
      }
    },
    setAttribute() {}, removeAttribute() {}, getAttribute() { return null; },
    focus() {}, blur() {},
    querySelector() { return makeEl(); },
    querySelectorAll() { return []; },
    closest() { return makeEl(); },
    cloneNode() { return makeEl(); },
  };
  Object.defineProperty(el, "content", { get() { return { firstElementChild: makeEl() }; } });
  return el;
}
globalThis.window = {
  matchMedia: () => ({ matches: false, addEventListener() {}, removeEventListener() {} }),
  addEventListener() {}, removeEventListener() {},
};
globalThis.location = { hash: "" };
globalThis.localStorage = { getItem: () => null, setItem() {}, removeItem() {} };
const elsById = new Map();
const elFor = (sel) => {
  let el = elsById.get(sel);
  if (!el) { el = makeEl(); elsById.set(sel, el); }
  return el;
};
globalThis.document = {
  cookie: "",
  body: makeEl(),
  documentElement: makeEl(),
  querySelector: elFor,
  querySelectorAll: () => [],
  createElement: () => makeEl(),
  createDocumentFragment: () => makeEl(),
  createTextNode: (t) => ({ nodeType: 3, data: t, textContent: t }),
  addEventListener() {}, removeEventListener() {},
};
globalThis.__MULLSMITH_TEST__ = true;
const { state, startGeneration } = await import("../assets/app/app.js");

function resetThread() {
  state.currentId = "FIXTURE";
  state.currentConv = { id: "FIXTURE" };
  state.navPendingId = "";
  state.reconcileId = "";
  state.inflight = null;
  state.meta = { models: [], default_model: "", show_reasoning: false };
  elFor("#thread").children = [];
}

// runStream feeds the recorded bytes through one startGeneration call.
// chunker controls how the bytes arrive (one blob by default).
async function runStream(frames, chunker = null) {
  const bytes = new TextEncoder().encode(frames);
  const parts = chunker ? chunker(bytes) : [bytes];
  let i = 0;
  globalThis.fetch = async () => ({
    ok: true,
    status: 200,
    body: {
      getReader: () => ({
        read: async () =>
          i < parts.length
            ? { value: parts[i++], done: false }
            : { value: undefined, done: true },
        cancel() {},
      }),
    },
  });
  resetThread();
  await startGeneration("/api/v1/conversations/FIXTURE/messages", { content: "x" }, () => {});
  return elFor("#thread").children;
}


// The assistant rows the same recording's history API returned, in order.
const historyIDs = fx.messages.items.filter((m) => m.role === "assistant").map((m) => m.id);

test("the recording really is a two-round exchange", () => {
  assert.equal(fx.events.includes("round"), true, "fixture predates the round event");
  assert.equal(historyIDs.length, 2, "fixture must contain two assistant rows");
});

test("live bubbles are keyed by the ids history returns, in order", async () => {
  const kids = await runStream(fx.frames);
  assert.equal(kids.length, 2, `two streamed rounds must paint two bubbles, got ${kids.length}`);
  assert.deepEqual(kids.map((k) => k.dataset.id), historyIDs,
    "a live bubble may not carry an id the stored rows do not");
});

test("bubble ids survive whatever chunk boundaries the bytes arrive on", async () => {
  // Every frame in one chunk, then one byte at a time: the ids must agree
  // either way (the boundary cannot decide where a round starts).
  const whole = await runStream(fx.frames);
  const bytes = new TextEncoder().encode(fx.frames);
  const byByte = await runStream(fx.frames, (b) => Array.from({ length: b.length }, (_, i) => b.subarray(i, i + 1)));
  assert.deepEqual(byByte.map((k) => k.dataset.id), whole.map((k) => k.dataset.id));
  assert.deepEqual(byByte.map((k) => k.dataset.id), historyIDs);
});
